static void require(bool ok,const juce::String& message){if(!ok)throw std::runtime_error(message.toStdString());}
static void pump(int ms){auto end=juce::Time::getMillisecondCounterHiRes()+ms;do{juce::MessageManager::getInstance()->runDispatchLoopUntil(2);[[NSRunLoop currentRunLoop]runMode:NSDefaultRunLoopMode beforeDate:[NSDate dateWithTimeIntervalSinceNow:.002]];}while(juce::Time::getMillisecondCounterHiRes()<end);}
static NSView* nativeView(juce::Component& c){require(c.getPeer()!=nullptr,"Missing native peer");return (__bridge NSView*)c.getPeer()->getNativeHandle();}
static void capture(juce::Component& component,const juce::File& file){NSView*view=nativeView(component);[view displayIfNeeded];NSBitmapImageRep*image=[view bitmapImageRepForCachingDisplayInRect:[view bounds]];[view cacheDisplayInRect:[view bounds]toBitmapImageRep:image];NSData*png=[image representationUsingType:NSBitmapImageFileTypePNG properties:@{}];require([png writeToFile:[NSString stringWithUTF8String:file.getFullPathName().toRawUTF8()]atomically:YES],"Native capture");}
static juce::AudioProcessorParameter* param(juce::AudioProcessor& p,int i){return p.getParameters()[i];}
static void ready(juce::AudioProcessor& p){for(int n=0;n<2000;n++){juce::AudioBuffer<float> block(2,128);block.clear();juce::MidiBuffer midi;p.processBlock(block,midi);pump(5);auto s=param(p,26)->getText(param(p,26)->getValue(),1024);if(s=="READY"&&n>=7)return;require(s=="LOADING"||s=="READY","Status parameter "+param(p,26)->getName(100)+" text=["+s+"] value="+juce::String(param(p,26)->getValue()));pump(5);}throw std::runtime_error("Loading timeout");}
class Head:public juce::AudioPlayHead{public:double ppq=0,rate=44100;bool playing=false;juce::Optional<PositionInfo> getPosition()const override{PositionInfo p;p.setBpm(120);p.setPpqPosition(ppq);p.setIsPlaying(playing);p.setTimeInSamples(int64_t(ppq*rate/2));return p;}};
static double audio(juce::AudioProcessor& p,Head& head,int note=60,bool notes=true,int blocks=160){double sum=0;int frames=0;juce::MidiBuffer midi;for(int n=0;n<blocks;n++){int count=std::array<int,5>{32,64,128,256,512}[n%5];juce::AudioBuffer<float>b(2,count);b.clear();midi.clear();if(notes&&n==0)midi.addEvent(juce::MidiMessage::noteOn(1,note,uint8_t(110)),0);if(notes&&n==110)midi.addEvent(juce::MidiMessage::noteOff(1,note),count-1);p.processBlock(b,midi);for(int c=0;c<2;c++)for(int f=0;f<count;f++){auto x=b.getSample(c,f);require(std::isfinite(x),"Nonfinite audio");sum+=x*x;}frames+=count;head.ppq+=count*2/head.rate;}return std::sqrt(sum/(frames*2));}
static void mouse(juce::Component&root,float x,float y,NSEventType type){NSView*view=nativeView(root);std::cout<<" ROOT "<<[[view className]UTF8String]<<" subviews="<<[[view subviews]count]<<std::endl;for(NSView*child in [view subviews]){std::cout<<" CHILD "<<[[child className]UTF8String]<<" hidden="<<[child isHidden]<<" frame="<<[[NSStringFromRect([child frame])description]UTF8String]<<" subviews="<<[[child subviews]count]<<std::endl;}NSPoint local=NSMakePoint(x,[view isFlipped]?y:NSHeight([view bounds])-y);std::cout<<"MOUSE root="<<root.getWidth()<<","<<root.getHeight()<<" native="<<NSWidth([view bounds])<<","<<NSHeight([view bounds])<<" flip="<<[view isFlipped]<<" local="<<local.x<<","<<local.y<<std::endl;NSPoint where=[view convertPoint:local toView:nil];NSPoint screen=[[view window]convertPointToScreen:where];std::cout<<" SCREEN "<<screen.x<<","<<screen.y<<" top="<<[NSWindow windowNumberAtPoint:screen belowWindowWithWindowNumber:0]<<" expected="<<[[view window]windowNumber]<<" frame="<<[NSStringFromRect([[view window]frame])UTF8String]<<std::endl;NSView*target=[view hitTest:[view convertPoint:local toView:[view superview]]];require(target!=nil,"Native view hit test");std::cout<<" target="<<[[target className]UTF8String]<<" window="<<[[view window]windowNumber]<<" event="<<where.x<<","<<where.y<<" targetLocal="<<[target convertPoint:where fromView:nil].x<<","<<[target convertPoint:where fromView:nil].y<<" targetBounds="<<[NSStringFromRect([target bounds])UTF8String]<<" targetWindow="<<[[target window]windowNumber]<<std::endl;NSEvent*event=[NSEvent mouseEventWithType:type location:where modifierFlags:0 timestamp:[NSProcessInfo processInfo].systemUptime windowNumber:[[view window]windowNumber] context:nil eventNumber:0 clickCount:1 pressure:1];SEL dispatch=NSSelectorFromString(type==NSEventTypeLeftMouseDown?@"asyncMouseDown:":@"asyncMouseUp:");if([target respondsToSelector:dispatch])[target performSelector:dispatch withObject:event];else if(type==NSEventTypeLeftMouseDown)[target mouseDown:event];else[target mouseUp:event];pump(25);}
static void click(juce::Component&root,const juce::String&name){const juce::StringArray names{"PLAY","EDIT","KIT"};int i=names.indexOf(name);require(i>=0,"Unknown tab");float x=22+(NSWidth([nativeView(root) bounds])-44)/3.f*(i+.5f);mouse(root,x,198,NSEventTypeLeftMouseDown);mouse(root,x,198,NSEventTypeLeftMouseUp);pump(120);}


#include "../native/Rhythmer Engines/src/third_party/json.hpp"
#include <set>
using Json=nlohmann::json;
static Json stateData(juce::AudioProcessor&p){juce::MemoryBlock b;p.getStateInformation(b);if(auto xml=juce::AudioProcessor::getXmlFromBinary(b.getData(),int(b.getSize()))){if(auto*component=xml->getChildByName("IComponent")){juce::MemoryBlock decoded;require(decoded.fromBase64Encoding(component->getAllSubText()),"VST3 component state decode");b=decoded;}}
 auto*d=(const uint8_t*)b.getData();size_t start=0;while(start+12<=b.getSize()&&std::memcmp(d+start,"MPCP",4)!=0)start++;require(start+12<=b.getSize(),"Missing canonical backend state");size_t at=start+8;auto u32=[&]{require(at+4<=b.getSize(),"State bounds");uint32_t v=d[at]|d[at+1]<<8|d[at+2]<<16|d[at+3]<<24;at+=4;return v;};auto n=u32();for(unsigned i=0;i<n;i++){require(at<b.getSize(),"State ID bounds");at+=1+d[at]+8;}auto len=u32();require(at+len<=b.getSize(),"State extra bounds");return Json::parse(d+at,d+at+len);}
static void settle(juce::AudioProcessor&p){juce::AudioBuffer<float>b(2,128);b.clear();juce::MidiBuffer m;p.processBlock(b,m);pump(15);stateData(p);}
static std::set<int> coverage(juce::AudioProcessor&p,int family,int cell,unsigned&pages){param(p,4)->setValue(family/3.f);param(p,5)->setValue(0);settle(p);int total=param(p,5)->getCurrentValueAsText().fromFirstOccurrenceOf("/",false,false).getIntValue();require(total>0&&total<=512,"Page count");std::set<int> ids;
for(int page=0;page<total;page++){param(p,5)->setValue(page/511.f);settle(p);auto data=stateData(p);for(int k=8;k<24;k++){uint64_t token=data["bindings"][k];if(!token)continue;require(((token>>16)&65535)==unsigned(cell),"Wrong edit pad");ids.insert(int(token&65535)-4);}pages++;}return ids;}
static void deepFormat(const juce::String&format,const juce::File&bundle,const Json&cat){void*handle=nullptr;if(format=="AudioUnit"){handle=dlopen(bundle.getChildFile("Contents/MacOS/Rhythmer Engines").getFullPathName().toRawUTF8(),RTLD_NOW|RTLD_LOCAL);require(handle,"AU load");auto factory=(AudioComponentFactoryFunction)dlsym(handle,"Rhythmer_EnginesAUFactory");AudioComponentDescription d{};d.componentType='aumu';d.componentSubType='Rhen';d.componentManufacturer='JzRh';require(AudioComponentRegister(&d,CFSTR("Rhythmer Release QA"),0x7fff0101,factory),"Register exact AU");}
juce::AudioPluginFormatManager manager;juce::addDefaultFormatsToManager(manager);juce::OwnedArray<juce::PluginDescription>types;for(auto*f:manager.getFormats())if(f->getName()==format)f->findAllTypesForFile(types,bundle.getFullPathName());require(types.size()==1,"Format discovery");juce::String error;auto plugin=manager.createPluginInstance(*types[0],44100,512,error);require(plugin!=nullptr,error);auto&p=*plugin;Head head;p.setPlayHead(&head);p.prepareToPlay(44100,512);ready(p);unsigned groups=0,names=0;
for(int engine=0;engine<int(cat["entries"].size())&&!std::getenv("RHYTHMER_QA_GEN_ONLY")&&!std::getenv("RHYTHMER_QA_KITS_ONLY");engine++){param(p,1)->setValue(engine/float(cat["entries"].size()-1));ready(p);const auto&list=engine==0?cat["kits"]:cat["sources"][int(cat["entries"][engine]["source_index"])]["sounds"];int control=engine==0?22:2,range=engine==0?int(list.size())-1:2047;
 for(int index:{0,int(list.size())/2,int(list.size())-1}){param(p,control)->setValue(index/float(range));ready(p);auto shown=param(p,2)->getCurrentValueAsText();require(shown==juce::String(list[index]["name"].get<std::string>()),"Preset name/selection mismatch "+juce::String(engine)+" "+shown);names++;}
 param(p,control)->setValue(0);ready(p);param(p,3)->setValue(10.f/15);settle(p);int cell=engine==0?10:0;auto all=coverage(p,0,cell,groups);std::set<int>parts;
 for(int section=1;section<=3;section++){auto ids=coverage(p,section,cell,groups);for(int id:ids)require(!parts.count(id),"Duplicate parameter sections");parts.insert(ids.begin(),ids.end());param(p,5)->setValue(0);settle(p);auto before=stateData(p);for(int k=0;k<8;k++){uint64_t token=before["bindings"][8+k];if(!token||int(token&65535)-4<0)continue;int index=14+k;param(p,index)->setValue(.371f);audio(p,head,engine==0?46:60);auto edited=stateData(p)["graph"];juce::MemoryBlock saved;p.getStateInformation(saved);param(p,1)->setValue((engine==18?3:18)/float(cat["entries"].size()-1));ready(p);p.setStateInformation(saved.getData(),int(saved.getSize()));ready(p);auto restored=stateData(p)["graph"];if(restored!=edited){std::cerr<<"STATE_OLD "<<edited["cells"][0]["values"].dump()<<" STATE_DIFF "<<Json::diff(edited,restored).dump()<<std::endl;throw std::runtime_error("Edited state restore");}break;}}
 require(all==parts,"Missing parameters from editor sections");std::cout<<format<<" ENGINE "<<engine<<" preset_selectors,parameters="<<all.size()<<",section_edit_state PASS"<<std::endl;}
// Every kit pad must sound, and a whole-kit save must restore its exact canonical controls.
for(int kit=std::getenv("RHYTHMER_QA_KIT_START")?std::atoi(std::getenv("RHYTHMER_QA_KIT_START")):0;kit<int(cat["kits"].size())&&!std::getenv("RHYTHMER_QA_GEN_ONLY");kit++){param(p,1)->setValue(0);param(p,22)->setValue(kit/float(cat["kits"].size()-1));ready(p);std::cout<<format<<" KIT_LOADING_DONE "<<kit<<std::endl;head.playing=false;for(int pad=0;pad<16;pad++){param(p,27)->setValue(1);audio(p,head,36+pad,false,2);require(audio(p,head,36+pad,true,48)>1e-8,"Silent kit pad "+juce::String(kit)+":"+juce::String(pad+1));}auto original=stateData(p)["graph"];juce::MemoryBlock saved;p.getStateInformation(saved);param(p,22)->setValue(((kit+1)%36)/35.f);ready(p);p.setStateInformation(saved.getData(),int(saved.getSize()));ready(p);require(stateData(p)["graph"]==original,"Kit state restore");std::cout<<format<<" KIT "<<kit<<" 16pads,state PASS"<<std::endl;}

// Generate through the real format editor, then round-trip its composition via
// the host state API. External MIDI is not emitted or internally replayed.
auto editor=std::unique_ptr<juce::AudioProcessorEditor>(p.createEditorAndMakeActive());require(editor!=nullptr,"Missing GEN editor");
editor->addToDesktop(juce::ComponentPeer::windowHasTitleBar);editor->setVisible(true);pump(150);
auto nativeClick=[&](float x,float y){mouse(*editor,x,y,NSEventTypeLeftMouseDown);mouse(*editor,x,y,NSEventTypeLeftMouseUp);pump(150);};
for(int engine:{0,1}){param(p,1)->setValue(engine/float(cat["entries"].size()-1));ready(p);pump(180);nativeClick(80,editor->getHeight()-123);nativeClick(110,editor->getHeight()-64);auto data=stateData(p);require(data.contains("desktop_midi"),"Native GEN interaction did not create composition");auto composition=data.at("desktop_midi");require(composition["notes"].size()>0,"Format GEN empty");juce::MemoryBlock saved;p.getStateInformation(saved);param(p,1)->setValue(18/float(cat["entries"].size()-1));ready(p);p.setStateInformation(saved.getData(),int(saved.getSize()));ready(p);require(stateData(p).at("desktop_midi")==composition,"Format GEN session restore mismatch");param(p,27)->setValue(1);audio(p,head,60,false,10);require(audio(p,head,60,false,100)<1e-8,"Offline GEN leaked playback");nativeClick(editor->getWidth()-100,48);}
editor->setVisible(false);editor->removeFromDesktop();
p.editorBeingDeleted(editor.get());editor.reset();std::cout<<format<<" MIDI_GEN_FORMAT_PASS kit,synth,composition_state,no_internal_playback"<<std::endl;
p.releaseResources();std::cout<<format<<(std::getenv("RHYTHMER_QA_GEN_ONLY")?" GEN_ONLY_PASS preset_checks=":" RELEASE_DEEP_PASS engines=20 preset_checks=")<<names<<" pages="<<groups<<" kits=36 pads=576"<<std::endl;}
int main(int argc,char**argv){juce::ScopedJuceInitialiser_GUI gui;try{require(argc==3,"Usage formats catalogue");Json cat;std::ifstream f(argv[2]);f>>cat;juce::File root(argv[1]);deepFormat("VST3",root.getChildFile("VST3/Rhythmer Engines.vst3"),cat);deepFormat("AudioUnit",root.getChildFile("AU/Rhythmer Engines.component"),cat);}catch(const std::exception&e){std::cerr<<"FAIL "<<e.what()<<std::endl;return 1;}std::cout<<"MAC_RELEASE_DEEP_PASS"<<std::endl;}
